private void reloadVideo(int delayMs) {
    if (getPlayer() == null) {
        return;
    }

    if (getPlayer().isEngineInitialized()) {
        Log.d(TAG, "Reloading the video...");
        Utils.postDelayed(mReloadVideo, delayMs);
