private void loadNextVideo(int delayMs) {
    if (getPlayer() == null) {
        return;
    }

    if (getPlayer().isEngineInitialized()) {
        Log.d(TAG, "Starting the next video...");
        Utils.postDelayed(mLoadNext, delayMs);
    }
}

