private void disposeActions() {
    MediaServiceManager.instance().disposeActions();
    RxHelper.disposeActions(mFormatInfoAction);
    Utils.removeCallbacks(mReloadVideo, mLoadNext, mRestartEngine, mMetadataSync);
}

