        options.add(UiOptionItem.from(getContext().getString(R.string.player_seek_confirmation_play),
                option -> {
                    mPlayerData.setSeekConfirmPauseEnabled(false);
                    mPlayerData.setSeekConfirmPlayEnabled(true);
